 88	    private <P> void registerReport(CsvReport<P, ?> report, Function<Context, P> readPeriod) {
 89	        server.get("/reports/" + report.name(), ctx -> {
 90	            P period = readPeriod.apply(ctx);
 91	            ctx.contentType("text/csv; charset=utf-8").result(report.generate(period));
 92	        });
 93	    }
 94	
 95	    private void registerErrorHandling() {
 96	        server.exception(HotelException.class, (exception, ctx) -> {
 97	            ctx.status(httpStatus(exception.errorCode()));
 98	            ctx.json(new ErrorResponse(exception.errorCode().name(), exception.getMessage()));
 99	        });
100	    }
101	
102	    private static int httpStatus(ErrorCode errorCode) {
103	        return switch (errorCode) {
104	            case INVALID_REQUEST -> 400;
105	            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
106	            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
107	            case CAPACITY_EXCEEDED -> 422;
108	        };
109	    }
110	
111	    private static NewReservation readNewReservation(Context ctx) {
112	        CreateReservationRequest body;
113	        try {
114	            body = ctx.bodyAsClass(CreateReservationRequest.class);
115	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
116	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
117	        }
118	        if (body == null
119	                || body.roomNumber() == null
120	                || isBlank(body.guestName())
121	                || isBlank(body.guestEmail())
122	                || isBlank(body.guestCpf())
123	                || body.checkIn() == null
124	                || body.checkOut() == null
125	                || body.guests() == null
126	                || body.ratePlan() == null) {
127	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
128	        }
129	        Guest guest = new Guest(body.guestName(), body.guestEmail(), body.guestCpf());
130	        return new NewReservation(
131	                body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
132	    }
133	
134	    private static long reservationId(Context ctx) {
135	        String id = ctx.pathParam("id");
136	        try {
137	            return Long.parseLong(id);
138	        } catch (NumberFormatException notANumber) {
139	            throw new HotelException(ErrorCode.RESERVATION_NOT_FOUND, "reservation " + id + " does not exist");
140	        }
141	    }
142	
143	    private static LocalDate readDate(Context ctx) {
144	        String date = requiredQueryParam(ctx, "date");
145	        try {
146	            return LocalDate.parse(date);
147	        } catch (DateTimeParseException badDate) {
148	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + date + "' is not a date (yyyy-MM-dd)");
149	        }
150	    }
151	
152	    private static YearMonth readMonth(Context ctx) {
153	        String month = requiredQueryParam(ctx, "month");
154	        try {
155	            return YearMonth.parse(month);
156	        } catch (DateTimeParseException badMonth) {
157	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + month + "' is not a month (yyyy-MM)");
158	        }
159	    }
160	
161	    private static String requiredQueryParam(Context ctx, String name) {
162	        String value = ctx.queryParam(name);
163	        if (value == null) {
164	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the query parameter '" + name + "' is required");
165	        }
166	        return value;
167	    }
168	
169	    private static boolean isBlank(String text) {
170	        return text == null || text.isBlank();
171	    }
172	}
