 2	
 3	import java.util.List;
 4	
 5	/**
 6	 * The shape every report shares: a title line (inn, report name and period), the header, one line per row
 7	 * and the total. Each report says only what is its own.
 8	 */
 9	public abstract class CsvReport<P, T> {
10	
11	    private static final String INN = "Pousada Maré Alta";
12	
13	    /** The report's name, as it appears in the title and in the URL. */
14	    public abstract String name();
15	
16	    protected abstract String header();
17	
18	    protected abstract List<T> rows(P period);
19	
20	    protected abstract String line(T row);
21	
22	    protected abstract String total(List<T> rows);
23	
24	    public final String generate(P period) {
25	        List<T> rows = rows(period);
26	        StringBuilder csv = new StringBuilder();
27	        csv.append(INN).append(',').append(name()).append(',').append(period).append('\n');
28	        csv.append(header()).append('\n');
29	        for (T row : rows) {
30	            csv.append(line(row)).append('\n');
31	        }
32	        csv.append(total(rows)).append('\n');
33	        return csv.toString();
34	    }
35	}
30	        return "reservation,room,check_in,check_out,guests,nights,tax";
31	    }
32	
33	    @Override
34	    protected List<Reservation> rows(YearMonth month) {
35	        List<Reservation> taxed = new ArrayList<>();
36	        for (Reservation reservation : store.all()) {
37	            if (reservation.isPaid() && YearMonth.from(reservation.checkIn()).equals(month)) {
38	                taxed.add(reservation);
39	            }
40	        }
41	        taxed.sort(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id));
42	        return taxed;
43	    }
44	
45	    @Override
46	    protected String line(Reservation reservation) {
47	        return reservation.id() + "," + reservation.roomNumber() + "," + reservation.checkIn() + ","
48	                + reservation.checkOut() + "," + reservation.guests() + "," + reservation.price().nights() + ","
49	                + tax(reservation).toPlainString();
50	    }
51	
52	    @Override
53	    protected String total(List<Reservation> rows) {
54	        BigDecimal total = BigDecimal.ZERO.setScale(2);
55	        for (Reservation reservation : rows) {
56	            total = total.add(tax(reservation));
57	        }
58	        return "total," + total.toPlainString();
59	    }
60	
61	    private BigDecimal tax(Reservation reservation) {
62	        BigDecimal guestNights = BigDecimal.valueOf((long) reservation.guests() * reservation.price().nights());
63	        return taxPerGuestNight.multiply(guestNights).setScale(2, RoundingMode.HALF_EVEN);
64	    }
